<div class="page-actions"><div><p class="mb-0">Tenant users, branch assignment, default/custom roles, dan granular permissions.</p></div><div class="d-flex gap-2"><button class="btn btn-outline-primary" data-bs-toggle="modal" data-bs-target="#roleModal">New Role</button><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#userModal">New User</button></div></div>
<div class="row g-3"><div class="col-lg-8"><div class="card-panel"><h3 class="h6 mb-3">Users</h3><table class="table datatable"><thead><tr><th>User</th><th>Branch</th><th>Role</th><th>Status</th><th>Last Login</th><th></th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= e($u['name']) ?></strong><small class="d-block text-secondary"><?= e($u['email']) ?></small></td><td><?= e($u['branch_name']??'-') ?></td><td><?= e($u['roles']??'No role') ?></td><td><span class="status-badge <?= $u['status']==='active'?'success':'' ?>"><?= e($u['status']) ?></span></td><td><?= e($u['last_login_at']??'-') ?></td><td><button class="btn btn-sm btn-light assign-role" data-id="<?= $u['id'] ?>" data-name="<?= e($u['name']) ?>">Role</button></td></tr><?php endforeach; ?></tbody></table></div></div><div class="col-lg-4"><div class="card-panel"><h3 class="h6 mb-3">Roles</h3><?php foreach($roles as $r): ?><div class="role-row"><div><strong><?= e($r['name']) ?></strong><small><?= e($r['code']) ?></small></div><span class="status-badge"><?= e($r['permission_count']) ?> permissions</span></div><?php endforeach; ?></div></div></div>
<div class="modal fade" id="userModal"><div class="modal-dialog"><form class="modal-content ajax-form" method="post" action="<?= url('/users') ?>"><?= csrf_field() ?><div class="modal-header"><h5>New User</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input class="form-control mb-2" name="name" placeholder="Full name" required><input class="form-control mb-2" type="email" name="email" placeholder="Email" required><input class="form-control mb-2" name="phone" placeholder="Phone"><input class="form-control mb-2" type="password" name="password" placeholder="Temporary password" minlength="8" required><label class="form-label">Branch</label><select class="form-select mb-2" name="branch_id"><option value="">None</option><?php foreach($branches as $b): ?><option value="<?= $b['id'] ?>"><?= e($b['name']) ?></option><?php endforeach; ?></select><label class="form-label">Initial Role</label><select class="form-select" name="role_id"><option value="">No role</option><?php foreach($roles as $r): ?><option value="<?= $r['id'] ?>"><?= e($r['name']) ?></option><?php endforeach; ?></select></div><div class="modal-footer"><button class="btn btn-primary">Create User</button></div></form></div></div>
<div class="modal fade" id="roleModal"><div class="modal-dialog modal-xl"><form class="modal-content ajax-form" method="post" action="<?= url('/roles') ?>"><?= csrf_field() ?><div class="modal-header"><h5>New Custom Role</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3 mb-3"><div class="col-md-6"><input class="form-control" name="name" placeholder="Role name" required></div><div class="col-md-6"><input class="form-control" name="code" placeholder="role_code"></div></div><div class="permission-grid"><?php $last='';foreach($permissions as $p): if($last!==$p['module']):$last=$p['module'];?><h6><?= e(ucfirst($last)) ?></h6><?php endif; ?><label><input class="form-check-input" type="checkbox" name="permissions[]" value="<?= $p['id'] ?>"> <span><?= e($p['name']) ?></span><small><?= e($p['code']) ?></small></label><?php endforeach; ?></div></div><div class="modal-footer"><button class="btn btn-primary">Create Role</button></div></form></div></div>
<div class="modal fade" id="assignRoleModal"><div class="modal-dialog"><form class="modal-content ajax-form" id="assignRoleForm" method="post"><?= csrf_field() ?><div class="modal-header"><h5>Assign Role</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><p id="assignRoleName"></p><select class="form-select" name="role_id" required><?php foreach($roles as $r): ?><option value="<?= $r['id'] ?>"><?= e($r['name']) ?></option><?php endforeach; ?></select></div><div class="modal-footer"><button class="btn btn-primary">Assign</button></div></form></div></div>
